    bool isPalindrome(string s) {
        string str = "";

        for (char ch : s){
            // static_cast to avoid undefined behaviour; not necessarily needed for LeetCode
            if (isalnum(static_cast<unsigned char>(ch))){
                str += tolower(ch);
            }
        }

        int l = 0;
        int r = str.length() - 1;

        while (l <= r){
            if (str[l] != str[r]){
                return false;
            }

            l++;
            r--;
        }
        
        return true;
    }
