class Solution:
    def evalRPN(self, tokens: list[str]) -> int:
        st = []
        
        for ch in tokens:
            if ch.isdigit() or (ch[0] == '-' and len(ch) > 1):
                st.append(int(ch))
            
            else:
                # In Python, .pop() also returns the value that was popped, so that we can store it in a variable
                num2 = st.pop()
                num1 = st.pop()

                if ch == '+':
                    st.append(num1 + num2)
                
                elif ch == '-':
                    st.append(num1 - num2)
                
                elif ch == '*':
                    st.append(num1 * num2)
                
                else:
                    st.append(int(num1 / num2))
        
        return st[0]

